                ('table', 'knowledge', 'segment_images', '', 'ai_gateway_knowledge_api', 'UPDATE'),
                ('table', 'knowledge', 'segment_images', '', 'ai_gateway_knowledge_worker', 'DELETE'),
                ('table', 'knowledge', 'segment_images', '', 'ai_gateway_knowledge_worker', 'INSERT'),
